import{_ as r,C as l,c as s,o as u,ag as o,j as t,G as n,a}from"./chunks/framework.Bw-5EFTY.js";const y=JSON.parse('{"title":"FluentCart Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/fluentcart-integration-with-fluentaffiliate.md","filePath":"guide/integrations/fluentcart-integration-with-fluentaffiliate.md","lastUpdated":1755766981000}'),c={name:"guide/integrations/fluentcart-integration-with-fluentaffiliate.md"};function f(g,e,d,h,p,m){const i=l("ZoomableImage");return u(),s("div",null,[e[0]||(e[0]=o('<h1 id="fluentcart-integration-with-fluentaffiliate" tabindex="-1">FluentCart Integration with FluentAffiliate <a class="header-anchor" href="#fluentcart-integration-with-fluentaffiliate" aria-label="Permalink to &quot;FluentCart Integration with FluentAffiliate&quot;">​</a></h1><p>FluentCart is a modern, lightweight e-commerce plugin for WordPress, designed to help you build and manage a high-performance online store. When you connect FluentCart with FluentAffiliate, you can launch a complete affiliate program to increase sales, track affiliate commissions, and handle payouts easily.</p><p>This guide will walk you through each step of integrating FluentCart with FluentAffiliate.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>To get started, you must have the FluentCart plugin installed and activated on your WordPress website.</p></div><h3 id="enable-the-fluentcart-integration" tabindex="-1">Enable the FluentCart Integration <a class="header-anchor" href="#enable-the-fluentcart-integration" aria-label="Permalink to &quot;Enable the FluentCart Integration&quot;">​</a></h3><p>First, you’ll need to activate the FluentCart module inside FluentAffiliate.</p><ol><li>Navigate to your <strong>FluentAffiliate Dashboard</strong>.</li><li>Click on the <strong>Settings</strong> tab located in the top menu.</li><li>From the settings menu on the left, select <strong>Integration Settings</strong>.</li><li>You will see a list of available integrations. Find <strong>FluentCart</strong> and click the toggle button to activate it.</li></ol><p>Once the integration is active, a <strong>Manage</strong> link will appear. Click this link to configure your FluentCart-specific affiliate settings.</p>',8)),t("p",null,[n(i,{src:"/guide/public/images/integrations/fluentcart/Integration-Settings-FluentAffiliate.webp",alt:"Integration Settings"})]),e[1]||(e[1]=t("h3",{id:"configure-fluentcart-settings",tabindex:"-1"},[a("Configure FluentCart Settings "),t("a",{class:"header-anchor",href:"#configure-fluentcart-settings","aria-label":'Permalink to "Configure FluentCart Settings"'},"​")],-1)),e[2]||(e[2]=t("p",null,"In the management panel, you can fine-tune how commissions work for your FluentCart store.",-1)),e[3]||(e[3]=t("p",null,"Here are the available options:",-1)),e[4]||(e[4]=t("ul",null,[t("li",null,[t("strong",null,"Enable Affiliate Integration for FluentCart:"),a(" This checkbox acts as the master switch for the integration. Ensure it is checked.")]),t("li",null,[t("strong",null,"Enable Branded Coupon Codes for Affiliates:"),a(" When you enable this feature, you can offer branded coupon codes to your affiliates. This allows them to promote products with unique discount codes, giving them another powerful marketing opportunity.")])],-1)),t("p",null,[n(i,{src:"/guide/public/images/integrations/fluentcart/branded-coupon-code.webp",alt:"Branded Coupon Code"})]),e[5]||(e[5]=o('<p>For example, this is perfect if you want to give a special coupon code to a social media influencer who is also one of your affiliates.To assign a coupon to a specific affiliate, follow these steps:</p><ol><li>From your WordPress dashboard, navigate to <strong>FluentCart &gt; Coupons</strong>.</li><li>Either click to create a new coupon or edit an existing one.</li><li>On the coupon editor page, look for the <strong>Fluent Affiliate</strong> section on the right-hand sidebar.</li><li>Click on the <strong>Select Affiliate</strong> field and begin typing the affiliate&#39;s name. Select their name from the list when it appears.</li><li><strong>Save</strong> the coupon. Now, when this coupon is used, the selected affiliate will be credited with the referral.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Before you can assign a coupon, the user must already be an approved affiliate in your FluentAffiliate program.</p></div>',3)),t("p",null,[n(i,{src:"/guide/public/images/integrations/fluentcart/select-affiliate-from-fluentcart.webp",alt:"Select Affiliate"})]),e[6]||(e[6]=o('<ul><li><p><strong>Disable Referrals on Upgrades:</strong> Check this box to ensure that no referrals will be added on purchased upgrades. This gives you more control over commission payouts for existing customers who upgrade their plan.</p></li><li><p><strong>Enable custom rate for specific products or categories:</strong> This is a powerful feature that lets you override your default commission rate. Check this box if you want to set special commission rates for specific products or entire product categories.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This feature gives you the flexibility to offer different commission rates for different products. For example, you could offer a higher commission on a new product as an incentive for affiliates to promote it more heavily.</p></div></li><li><p><strong>Select Products:</strong> In the <code>Select</code> field, start typing the name of the product or category and choose it from the list.</p></li><li><p><strong>Select Rate:</strong> Enter the commission value in the <code>Enter Rate</code> field. Then, choose whether the commission is a <strong>Percentage (%)</strong> or a <strong>Fixed</strong> amount from the dropdown menu.</p></li><li><p><strong>Save Settings:</strong> Once you have configured all your custom rates, click the Save Settings button to make them live.</p></li></ul><p>You can add more custom rates for different products or categories by clicking the <strong>+Add New Group</strong> button again. You can also remove any rate rule by clicking the red <code>delete</code> icon.</p>',2)),t("p",null,[n(i,{src:"/guide/public/images/integrations/fluentcart/specific-product-or-categories.webp",alt:"Add New Group"})]),e[7]||(e[7]=o('<h3 id="generate-an-affiliate-link" tabindex="-1">Generate an Affiliate Link <a class="header-anchor" href="#generate-an-affiliate-link" aria-label="Permalink to &quot;Generate an Affiliate Link&quot;">​</a></h3><p>Once you&#39;ve finished setting up your FluentCart product settings, it&#39;s time to generate your <a href="/guide/affiliate-portal/generating-affiliate-links">affiliate link</a>.</p><p>Whenever a customer makes a purchase using this link, the affiliate will earn a commission based on the rates you have configured.</p><h3 id="troubleshooting-common-issues" tabindex="-1">Troubleshooting Common Issues <a class="header-anchor" href="#troubleshooting-common-issues" aria-label="Permalink to &quot;Troubleshooting Common Issues&quot;">​</a></h3><p>If you encounter any issues, here are some solutions to common problems:</p><ul><li><strong>Commissions Not Tracking:</strong> Verify that the integration toggle for FluentCart is enabled in the Integration Settings. You can also test your affiliate link with a purchase to ensure it is working correctly.</li><li><strong>Affiliate Links Not Generating:</strong> Verify that the product URL you are using is valid and the page is publicly accessible. Also, ensure that FluentAffiliate is fully integrated with FluentCart in the Integration Settings.</li><li><strong>Custom Rates Not Applying:</strong> If a product-specific or category-specific rate isn&#39;t being applied, double-check your custom rate rules in the integration settings to ensure they are configured correctly and that there are no conflicting rules.</li></ul>',6))])}const w=r(c,[["render",f]]);export{y as __pageData,w as default};
